"""Reproduce the small oracle table from SHA-pinned official Unicode 16 UCD.

Run with --source-dir for offline inputs, or --download for official sources.
--check compares generated bytes without rewriting the checked-in table.
"""

import argparse
import hashlib
import json
from pathlib import Path
import urllib.request

DATA = Path(__file__).resolve().parent.parent / "fixtures/oracle/unicode16"


def extract(sources):
    lower = {}
    for line in sources["UnicodeData.txt"].splitlines():
        fields = line.split(";")
        if fields[13]:
            lower[int(fields[0], 16)] = [int(fields[13], 16)]
    contexts = {}
    for line in sources["SpecialCasing.txt"].splitlines():
        body = line.split("#", 1)[0].strip()
        if not body:
            continue
        fields = [field.strip() for field in body.split(";")]
        point = int(fields[0], 16)
        mapping = [int(value, 16) for value in fields[1].split()]
        condition = fields[4]
        if not condition:
            lower[point] = mapping
        elif condition == "Final_Sigma":
            contexts[str(point)] = {"condition": condition, "lower": mapping}
        elif condition.split()[0] not in {"tr", "az", "lt"}:
            raise ValueError("unsupported default SpecialCasing context")
    properties = {"Cased": [], "Case_Ignorable": []}
    for line in sources["DerivedCoreProperties.txt"].splitlines():
        body = line.split("#", 1)[0].strip()
        if not body:
            continue
        fields = [field.strip() for field in body.split(";")]
        if fields[1] in properties:
            bounds = [int(value, 16) for value in fields[0].split("..")]
            properties[fields[1]].append([bounds[0], bounds[-1]])
    for name, ranges in properties.items():
        merged = []
        for start, end in sorted(ranges):
            if merged and start <= merged[-1][1] + 1:
                merged[-1][1] = max(merged[-1][1], end)
            else:
                merged.append([start, end])
        properties[name] = merged
    return {"unicode_version": "16.0.0",
            "lower": {str(point): value for point, value in sorted(lower.items())
                      if value != [point]},
            "contexts": contexts, "properties": properties}


def encode_table(table):
    return (json.dumps(table, sort_keys=True, separators=(",", ":")) + "\n").encode()


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    source = parser.add_mutually_exclusive_group(required=True)
    source.add_argument("--source-dir", type=Path)
    source.add_argument("--download", action="store_true")
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    manifest = json.loads((DATA / "manifest.json").read_bytes())
    sources = {}
    for name, entry in manifest["sources"].items():
        if args.source_dir:
            payload = (args.source_dir / name).read_bytes()
        else:
            with urllib.request.urlopen(entry["url"], timeout=45) as response:
                payload = response.read()
        if hashlib.sha256(payload).hexdigest() != entry["sha256"]:
            raise ValueError(f"source checksum mismatch: {name}")
        sources[name] = payload.decode("utf-8")
    payload = encode_table(extract(sources))
    digest = hashlib.sha256(payload).hexdigest()
    if digest != manifest["table_sha256"]:
        raise ValueError("extracted table checksum mismatch")
    if sources["LICENSE.txt"].encode() != (DATA / "LICENSE.txt").read_bytes():
        raise ValueError("license bytes mismatch")
    target = DATA / "lowercase.json"
    if args.check:
        if target.read_bytes() != payload:
            raise ValueError("checked-in table differs from extraction")
    else:
        target.write_bytes(payload)
    print(json.dumps({"unicode_version": "16.0.0", "sha256": digest,
                      "source_hashes_checked": len(sources), "check": args.check}))


if __name__ == "__main__":
    main()
